/* D3 7.9.0 is the only chart renderer. Every report SVG is produced here in the HTML. */
const D=window.REPORT_DATA, F=window.FIGURE_CATALOG.filter(f=>!['f17','f18'].includes(f.id));
const S=D.originalAnalysis,P=D.posts,A=D.originalRecords,C=A.filter(d=>d.caption_eligible),R=A.filter(d=>d.ranking_eligible);
const ink='#10253F',muted='#485B70',grid='#D9E2EB',blue='#00689D',red='#E5243B',paper='#FFFFFF';
const TN=S.topic_names,AN=S.approach_names, topics=Object.keys(TN), approaches=Object.keys(AN), years=['2023','2024','2025','2026'];
const TC=Object.fromEntries(topics.map(t=>[t,D.colors[TN[t]]])), AC=Object.fromEntries(approaches.map((a,i)=>[a,[blue,'#4C9F38',red,'#FCC30B','#DD1367','#FD6925'][i]])),YC={'2023':'#FCC30B','2024':'#00689D','2025':'#E5243B','2026':'#4C9F38'};
const index=new Map(P.map(d=>[d.id,d])); const fmt=v=>v==null?'—':Number.isInteger(v)?String(v):d3.format('.1f')(v);
const med=(arr,k)=>d3.median(arr,d=>+d[k]); const group=(arr,key)=>Array.from(d3.group(arr,d=>d[key]),([key,values])=>({key,values}));
function txt(g,x,y,text,size=20,fill=ink,weight=400,anchor='start'){return g.append('text').attr('x',x).attr('y',y).attr('font-size',size).attr('fill',fill).attr('font-weight',weight).attr('text-anchor',anchor).text(text)}
function wrap(g,x,y,text,width,size=20,fill=ink,weight=400,line=1.25){let el=txt(g,x,y,'',size,fill,weight), words=text.split(/\s+/), row=[],dy=0;for(const w of words){row.push(w);if(row.join(' ').length*size*.51>width&&row.length>1){row.pop();el.append('tspan').attr('x',x).attr('dy',dy?size*line:0).text(row.join(' '));dy++;row=[w]}}el.append('tspan').attr('x',x).attr('dy',dy?size*line:0).text(row.join(' '));return el}
function line(g,x1,y1,x2,y2,color=grid,width=1,dash=null){return g.append('line').attr('x1',x1).attr('y1',y1).attr('x2',x2).attr('y2',y2).attr('stroke',color).attr('stroke-width',width).attr('stroke-dasharray',dash)}
function panel(svg,x,y,title){const g=svg.append('g').attr('transform',`translate(${x},${y})`);if(title)txt(g,0,0,title,22,ink,600);return g}
function axes(g,x,y,w,h,xlabel,ylabel){g.append('g').attr('transform',`translate(0,${h})`).call(d3.axisBottom(x).ticks(5).tickSize(0).tickPadding(12));g.append('g').call(d3.axisLeft(y).ticks(5).tickSize(-w).tickPadding(10)).call(s=>s.select('.domain').remove()).call(s=>s.selectAll('.tick line').attr('stroke',grid));g.selectAll('.domain').attr('stroke',grid);g.selectAll('.tick text').attr('fill',muted).attr('font-size',17);if(xlabel)txt(g,w/2,h+55,xlabel,18,muted,400,'middle');if(ylabel)txt(g,0,-17,ylabel,18,muted);}
function legend(g,items,x,y,step=150,size=17){items.forEach((it,i)=>{g.append('circle').attr('cx',x+i*step).attr('cy',y-5).attr('r',5).attr('fill',it[1]);txt(g,x+12+i*step,y,it[0],size,muted)})}
function tip(sel,fn){sel.attr('data-detail',fn).attr('tabindex',0).attr('role','button');sel.append('title').text(fn);return sel}
function dot(g,x,y,r,color){return g.append('circle').attr('cx',x).attr('cy',y).attr('r',r).attr('fill',color)}
function frame(spec){let s=d3.create('svg').attr('xmlns','http://www.w3.org/2000/svg').attr('width',1000).attr('height',spec.height).attr('viewBox',`0 0 1000 ${spec.height}`).attr('role','img').attr('aria-label',spec.title).attr('data-figure-id',spec.id).attr('font-family','Arial, sans-serif');s.append('title').text(spec.title);s.append('desc').text(spec.basis+'. '+spec.note);s.append('rect').attr('width',1000).attr('height',spec.height).attr('fill',paper);txt(s,30,33,`${String(spec.number).padStart(2,'0')}  /  ${spec.chapter.toUpperCase()}`,14,blue,600);txt(s,30,72,spec.title,29,ink,600);txt(s,30,100,spec.basis,17,muted);line(s,30,spec.height-32,970,spec.height-32);txt(s,30,spec.height-12,'RIAD MEDDEB  ·  LINKEDIN VISUAL ANALYSIS  ·  02 OCT 2026',12,muted);txt(s,970,spec.height-12,'D3 / '+spec.id.toUpperCase(),12,muted,400,'end');return s}
function lightLabel(color){const c=d3.rgb(color),v=[c.r,c.g,c.b].map(n=>{n/=255;return n<=.04045?n/12.92:((n+.055)/1.055)**2.4}),L=.2126*v[0]+.7152*v[1]+.0722*v[2];return 1.05/(L+.05)>(L+.05)/.068;}
function heat(svg,{x=30,y=150,w=940,h=340,rows,cols,value,count,title='',labels=170,colors=[paper,blue],min=3,max=null}){const g=panel(svg,x,y,title),cw=(w-labels)/cols.length,ch=(h-48)/rows.length;let vals=rows.flatMap(r=>cols.map(c=>value(r,c))).filter(v=>v!=null);const cs=d3.scaleLinear().domain([0,max??d3.max(vals)??1]).range(colors);cols.forEach((c,j)=>wrap(g,labels+j*cw+cw/2,36,c,cw-6,16,muted).attr('text-anchor','middle'));rows.forEach((r,i)=>{let yy=57+i*ch;wrap(g,labels-15,yy+ch/2-2,r,labels-18,17,ink).attr('text-anchor','end');cols.forEach((c,j)=>{const v=value(r,c),n=count?count(r,c):null,valid=v!=null&&(n==null||n>=min),xx=labels+j*cw;tip(g.append('rect').attr('x',xx).attr('y',yy).attr('width',cw-4).attr('height',ch-4).attr('rx',3).attr('fill',valid?cs(v):'#EDF1F5'),()=>`${r} · ${c} · ${title||svg.attr('aria-label')}: ${valid?fmt(v):'Not available / below minimum sample'}${n!=null?' · n='+n:''}`).attr('data-focus',r);const dark=valid&&lightLabel(cs(v));txt(g,xx+(cw-4)/2,yy+ch*.48,valid?fmt(v):(n?'n='+n:'—'),valid?20:15,dark?'white':(valid?ink:muted),valid?600:400,'middle');if(n!=null&&valid)txt(g,xx+(cw-4)/2,yy+ch*.79,'n='+n,13,dark?'#FFFFFF':muted,400,'middle')})});return g}
function scatter(svg,{x=85,y=190,w=350,h=270,data,xkey,ykey,xlabel,ylabel,color=d=>YC[d.year],radius=d=>4.5,xmax=null,ymax=null}){const g=panel(svg,x,y);const sx=d3.scaleLinear().domain([0,xmax||d3.max(data,d=>+d[xkey])*1.08]).nice().range([0,w]),sy=d3.scaleLinear().domain([0,ymax||d3.max(data,d=>+d[ykey])*1.08]).nice().range([h,0]);axes(g,sx,sy,w,h,xlabel,ylabel);tip(g.selectAll('circle.mark').data(data).join('circle').attr('class','mark').attr('cx',d=>sx(+d[xkey])).attr('cy',d=>sy(+d[ykey])).attr('r',radius).attr('fill',color).attr('fill-opacity',.9).attr('stroke',paper).attr('stroke-width',.6),d=>`${d.activity_id?(index.get(d.activity_id)?.title||d.activity_id):(d.month||'Observation')} · ${d.year||''} · ${xlabel}: ${fmt(d[xkey])} · ${ylabel}: ${fmt(d[ykey])}${d.n?' · n='+d.n:''}`).attr('data-focus',d=>d.year).attr('data-post',d=>d.activity_id||null);return {g,sx,sy}}
function imageTile(g,p,x,y,w,h,label=true){g.append('rect').attr('x',x).attr('y',y).attr('width',w).attr('height',h).attr('rx',2).attr('fill','#F0F3F7');if(p.embedded){let im=g.append('image').attr('x',x+2).attr('y',y+2).attr('width',w-4).attr('height',h-(label?17:4)).attr('preserveAspectRatio','xMidYMid meet').attr('data-src',p.embedded).attr('data-record-id',p.id).attr('data-index',p.index).attr('data-focus',p.year).attr('data-detail',`Post ${p.index} · ${p.date} · ${p.title} · ${fmt(p.reactions)} reactions · ${fmt(p.comments)} comments`).attr('tabindex',0).attr('role','button').attr('aria-label',`Post ${p.index}: ${p.title}`).style('cursor','pointer').on('click',()=>showPost(p)).on('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showPost(p)}});im.append('title').text(`${p.index} · ${p.date} · ${p.title}`)}else{txt(g,x+w/2,y+h/2,'No image',Math.min(12,w/8),muted,400,'middle');tip(g.append('rect').attr('x',x).attr('y',y).attr('width',w).attr('height',h).attr('fill','transparent').attr('data-record-id',p.id).attr('data-index',p.index).attr('data-post',p.id).attr('data-focus',p.year),()=>`Post ${p.index} · ${p.date} · ${p.title} · No standalone image`)}if(label)txt(g,x+4,y+h-4,String(p.index).padStart(3,'0'),Math.max(8,Math.min(12,w/7)),muted)}
function mosaic(svg,key,order,height){let rows=key?order.map(k=>[k,P.filter(p=>p[key]===k)]):[['All posts',P]], x0=30,y=135,w=940,gap=4,cols=20,cw=(w-gap*(cols-1))/cols;let totalLines=rows.reduce((s,[k,v])=>s+Math.ceil(v.length/cols),0),head=28;let ch=Math.min(64,(height-y-58-(head+7)*rows.length)/totalLines);for(const[k,vals]of rows){txt(svg,x0,y+17,`${k}  ·  ${vals.length}`,17,ink,600);y+=head;vals.sort((a,b)=>a.date.localeCompare(b.date)||a.index-b.index).forEach((p,i)=>imageTile(svg,p,x0+(i%cols)*(cw+gap),y+Math.floor(i/cols)*ch,cw,ch-gap));y+=Math.ceil(vals.length/cols)*ch+7}}
const renderers={};
renderers.f01=s=>{const cols=d3.range(1,13).map(m=>d3.timeFormat('%b')(new Date(2020,m-1,1)));heat(s,{y:130,h:245,rows:years,cols,labels:90,min:0,value:(r,c)=>{let m=r+'-'+String(cols.indexOf(c)+1).padStart(2,'0');return m<'2023-03'||m>'2026-09'?null:P.filter(p=>p.month===m).length}});txt(s,30,450,'Annual context · medians use the original eligible captions',20,ink,600);const xs=[35,210,365,545,725,930],heads=['Year','Recovered','Eligible captions','Words','Reactions','Comments'];heads.forEach((v,i)=>txt(s,xs[i],490,v,17,muted,500,i?'end':'start'));S.years.forEach((r,j)=>{let yy=527+j*38,vals=[r.year,D.summary.years[r.year],r.n,fmt(r.words),fmt(r.reactions),fmt(r.comments)];line(s,30,yy+12,950,yy+12);vals.forEach((v,i)=>tip(txt(s,xs[i],yy,v,19,ink,500,i?'end':'start'),()=>`${r.year} · ${heads[i]}: ${v}${i===1?' recovered records only; yearly history incomplete':''}`).attr('data-focus',r.year))})};
renderers.f02=s=>{const qs=d3.range(15).map(i=>{let year=2023+Math.floor(i/4),q=year+'Q'+(i%4+1);return S.quarterly.find(d=>d.quarter===q)||{quarter:q,n:0,reactions:null,comments:null}});['reactions','comments'].forEach((k,i)=>{let g=panel(s,95,160+i*181,i?'Median comments':'Median reactions'),w=830,h=120,x=d3.scalePoint().domain(qs.map(d=>d.quarter)).range([0,w]),y=d3.scaleLinear().domain([0,d3.max(qs,d=>d[k])*1.1]).nice().range([h,0]);g.append('g').call(d3.axisLeft(y).ticks(3).tickSize(-w)).call(g=>g.select('.domain').remove()).call(g=>g.selectAll('line').attr('stroke',grid));g.selectAll('.tick text').attr('font-size',16).attr('fill',muted);g.append('path').datum(qs).attr('d',d3.line().defined(d=>d.n>=3).x(d=>x(d.quarter)).y(d=>y(d[k]))).attr('fill','none').attr('stroke',i?red:blue).attr('stroke-width',3);tip(g.selectAll('circle').data(qs.filter(d=>d.n>=3)).join('circle').attr('cx',d=>x(d.quarter)).attr('cy',d=>y(d[k])).attr('r',5).attr('fill',i?red:blue),d=>`${d.quarter} · Median ${k}: ${fmt(d[k])} · n=${d.n}`).attr('data-focus',d=>d.quarter.slice(0,4));if(i)g.append('g').attr('transform',`translate(0,${h})`).call(d3.axisBottom(x).tickFormat(q=>q.slice(2,4)+' '+q.slice(4)).tickSize(0).tickPadding(12)).selectAll('text').attr('font-size',15).attr('fill',muted)});};
