function stacked(svg,{field,keys,names,colors,x=30,y=155,w=430,h=255}){let g=panel(svg,x,y,'Share of eligible captions'),ys=['2024','2025','2026'],left=54,cw=(w-left)/3;ys.forEach((yr,i)=>{let arr=C.filter(d=>d.year===yr),top=35;keys.forEach(k=>{let n=arr.filter(d=>d[field]===k).length,hh=n/arr.length*h;let r=g.append('rect').attr('x',left+i*cw).attr('y',top).attr('width',cw*.60).attr('height',hh).attr('fill',colors[k]);tip(r,()=>`${yr} · ${names[k]}: ${n} captions (${fmt(n/arr.length*100)}%)`).attr('data-focus',names[k]);top+=hh});txt(g,left+i*cw+cw*.3,h+64,yr,19,ink,400,'middle')});[0,50,100].forEach(v=>txt(g,35,35+h-v/100*h+5,v+'%',15,muted,400,'end'));return g}
