 label(s,8,18,'TOPIC',11,muted,'start',700);label(s,w-8,18,'WRITING APPROACH',11,muted,'end',700);
 const links=s.append('g');const nodes=s.append('g');const highlight=(topic,approach)=>links.selectAll('path').attr('opacity',d=>(!topic||d.topic===topic)&&(!approach||d.approach===approach)?.76:.09);
